using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Draftmaster.MasterDraft;
using Draftmaster.Tracks;
using NUnit.Framework;

// Master Draft's series: Assets/Resources/MasterDraft/Series.json (generated by Tools/masterdraft_export.py from
// Draftmaster 2's SeriesData.cs), the shared restriction engine (Core Restrictions.cs) and championships (Core
// SeriesRules.cs). Engine-free — reads the files off disk — so it also runs under `dotnet test Tools/HeadlessTests`.
public class MasterDraftSeriesTests
{
    // DM2's menus in order and how many series each holds ("Mods" had none of its own and isn't exported).
    static readonly (string id, int count)[] ExpectedMenus =
    {
        ("rookies", 5), ("superspeedways", 5), ("cookie_cutters", 5), ("short_tracks", 5), ("class", 5),
        ("team", 24), ("manufacturer", 8), ("type", 6), ("rarity", 4), ("seasons", 10),
    };

    static string projectRoot;

    static string ProjectRoot()
    {
        if (projectRoot != null) return projectRoot;
        foreach (var start in new[] { TestContext.CurrentContext.TestDirectory, Directory.GetCurrentDirectory() })
        {
            for (var dir = new DirectoryInfo(start); dir != null; dir = dir.Parent)
                if (File.Exists(Path.Combine(dir.FullName, "Assets", "Resources", "MasterDraft", "Series.json")))
                    return projectRoot = dir.FullName;
        }
        Assert.Fail("Assets/Resources/MasterDraft/Series.json not found above " + TestContext.CurrentContext.TestDirectory);
        return null;
    }

    static string Resource(string path) => File.ReadAllText(Path.Combine(ProjectRoot(), "Assets", "Resources", path + ".json"));

    static DraftSeriesCatalog LoadSeries()
    {
        var s = DraftSeriesCatalog.FromJson(Resource(DraftSeriesCatalog.ResourcePath));
        Assert.IsNotNull(s, "Series.json did not parse");
        return s;
    }

    static CarCatalog LoadCars()
    {
        var c = CarCatalog.FromJson(Resource(CarCatalog.ResourcePath));
        Assert.IsNotNull(c, "Cars.json did not parse");
        return c;
    }

    static CarDef Car(string id = "t_1", int number = 1, string team = "HEN", string manu = "CHV", int rarity = 2,
        string type = "Closer", string driver = "Driver", string carset = "t") =>
        new CarDef { id = id, carset = carset, number = number, team = team, manufacturer = manu, rarity = rarity, type = type, driver = driver };

    // ---- Series.json ------------------------------------------------------------------------------------

    [Test]
    public void FileHasEveryMenuAndSeriesInOrder()
    {
        var file = (SeriesFile)ProfileJson.Read(Resource(DraftSeriesCatalog.ResourcePath), typeof(SeriesFile));
        Assert.AreEqual(1, file.version);
        var s = new DraftSeriesCatalog(file);
        CollectionAssert.AreEqual(ExpectedMenus.Select(m => m.id).ToArray(), s.Menus.Select(m => m.id).ToArray());
        foreach (var (id, count) in ExpectedMenus)
            Assert.AreEqual(count, s.GetMenu(id).series.Count, id);
        Assert.AreEqual(ExpectedMenus.Sum(m => m.count), s.All.Count, "the catalogue dropped series (blank id, no rounds, repeated id)");
        Assert.AreEqual(s.All.Count, s.All.Select(x => x.id).Distinct().Count());
    }

    [Test]
    public void FirstRookieSeriesMatchesDm2()
    {
        var s = LoadSeries().Get("rookies_take_the_wheel");
        Assert.IsNotNull(s);
        Assert.AreEqual("Take The Wheel", s.name);
        CollectionAssert.AreEqual(new[] { 0, 0 }, s.dm2Index);
        Assert.AreEqual(0, s.aiLevel);
        Assert.AreEqual(1, s.restriction.minLevel);
        Assert.AreEqual(0, s.restriction.minClass);
        Assert.IsFalse(s.restriction.HasRule);
        Assert.AreEqual("Rookies", s.prize.code);
        Assert.AreEqual("Rookie", s.prize.driverType);
        // DM2 tracklist "1,2,4": Daytona, Atlanta, Phoenix with their base laps.
        CollectionAssert.AreEqual(new[] { "Daytona", "Atlanta", "Phoenix" }, s.rounds.Select(r => r.track).ToArray());
        CollectionAssert.AreEqual(new[] { 4, 5, 6 }, s.rounds.Select(r => r.baseLaps).ToArray());
    }

    [Test]
    public void CustomListOrderIsKept()
    {
        // DM2 offlineCustomListOrder[5] = "0,11,18,1,...": Lone Ranger, Ware On Earth, Flip Of A Coyne, The Tallest Spire.
        var team = LoadSeries().GetMenu("team");
        CollectionAssert.AreEqual(new[] { "Lone Ranger", "Ware On Earth", "Flip Of A Coyne", "The Tallest Spire" },
            team.series.Take(4).Select(x => x.name).ToArray());
    }

    [Test]
    public void EveryRoundIsARealCatalogueTrack()
    {
        foreach (var s in LoadSeries().All)
            foreach (var r in s.rounds)
            {
                Assert.IsTrue(TrackDimensions.Has(r.track), $"{s.id}: '{r.track}' is not a TrackCatalog id");
                Assert.Greater(r.baseLaps, 0, s.id);
            }
    }

    [Test]
    public void Dm2TrackMappingKeepsTheTrackKindAndExplainsSubstitutes()
    {
        var series = LoadSeries();
        Assert.Greater(series.Dm2Tracks.Count, 0);
        foreach (var row in series.Dm2Tracks)
        {
            Assert.IsTrue(TrackDimensions.TryGet(row.track, out var dims), $"DM2 track {row.dm2Id} -> unknown '{row.track}'");
            Assert.AreEqual(row.kind, dims.kind.ToString(), $"DM2 track {row.dm2Id} ({row.dm2Name}) changed kind going to {row.track}");
        }
        // Venues the catalogue lacks go to a same-kind track and say why.
        var fontana = series.Dm2Tracks.Single(t => t.dm2Id == 5);
        Assert.AreEqual("Michigan", fontana.track);
        Assert.IsNotEmpty(fontana.note);
        Assert.AreEqual("Gateway", series.Dm2Tracks.Single(t => t.dm2Id == 22).track);
        Assert.AreEqual("BowmanGray", series.Dm2Tracks.Single(t => t.dm2Id == 30).track);
        // And every DM2 track a series uses has a row.
        var rowIds = new HashSet<int>(series.Dm2Tracks.Select(t => t.dm2Id));
        foreach (var s in series.All)
            foreach (var r in s.rounds)
                Assert.IsTrue(rowIds.Contains(r.dm2Track), $"{s.id}: DM2 track {r.dm2Track} has no mapping row");
    }

    [Test]
    public void EverySeriesHasCarsThatFitAndAPrizePool()
    {
        var cars = LoadCars();
        foreach (var s in LoadSeries().All)
        {
            Assert.IsTrue(RestrictionRule.IsValid(s.restriction.rule), $"{s.id}: rule '{s.restriction.rule}'");
            Assert.IsNotEmpty(Restrictions.FittingCars(s.restriction, cars), $"{s.id}: no car can enter");
            Assert.That(s.restriction.minClass, Is.InRange(CarProgression.MinClass, CarProgression.MaxClass), s.id);
            Assert.That(s.aiLevel, Is.InRange(0, SeriesRules.MaxAILevel), s.id);
            if (s.prize.IsNone) continue;
            Assert.IsNotEmpty(SeriesRules.PrizePool(s, cars), $"{s.id}: prize '{s.prize.code}' matches no car");
        }
    }

    [Test]
    public void Dm2PrizeCodesBecomeFilters()
    {
        var series = LoadSeries();
        var cars = LoadCars();
        var mustang = series.Get("manufacturer_mustang_sally").prize;   // "FRD1": Fords, one star
        Assert.AreEqual("FRD", mustang.manufacturer);
        Assert.AreEqual(1, mustang.minRarity);
        Assert.AreEqual(1, mustang.maxRarity);
        Assert.IsTrue(SeriesRules.PrizePool(series.Get("manufacturer_mustang_sally"), cars).All(c => c.manufacturer == "FRD" && c.rarity == 1));

        var born = series.Get("rarity_born_to_win").prize;               // "Rarity3Plus"
        Assert.AreEqual(3, born.minRarity);
        Assert.AreEqual(0, born.maxRarity);

        var indy = series.Get("seasons_2003_indy_ovals").prize;          // "Indy": the IndyCar carsets
        CollectionAssert.AreEquivalent(new[] { "irl23", "irl24", "irc00" }, indy.carsets);

        Assert.IsTrue(series.Get("seasons_half_season_1").prize.IsNone);
        Assert.IsEmpty(SeriesRules.PrizePool(series.Get("seasons_half_season_1"), cars));
    }

    [Test]
    public void RestrictionRulesComeThroughFromDm2()
    {
        var series = LoadSeries();
        var lone = series.Get("team_lone_ranger").restriction;
        Assert.AreEqual(RestrictionRule.Team, lone.rule);
        Assert.AreEqual("IND", lone.value);
        var heavy = series.Get("manufacturer_heavy_chevy").restriction;
        Assert.AreEqual(RestrictionRule.Manufacturer, heavy.rule);
        Assert.AreEqual("CHV", heavy.value);
        Assert.AreEqual(5, heavy.minClass);
        var legend = series.Get("type_legend_of_the_sport").restriction;
        Assert.AreEqual(RestrictionRule.Type, legend.rule);
        Assert.AreEqual("Legend", legend.value);
        var born = series.Get("rarity_born_to_win").restriction;
        Assert.AreEqual(RestrictionRule.Rarity, born.rule);
        Assert.AreEqual("4", born.value);
        Assert.AreEqual(40, born.minLevel);
    }

    [Test]
    public void MenusUnlockAtTheirLowestSeriesLevel()
    {
        var series = LoadSeries();
        Assert.AreEqual(1, DraftSeriesCatalog.MenuMinLevel(series.GetMenu("rookies")));
        Assert.AreEqual(10, DraftSeriesCatalog.MenuMinLevel(series.GetMenu("manufacturer")));
        Assert.IsFalse(DraftSeriesCatalog.MenuUnlocked(series.GetMenu("rarity"), 9));
        Assert.IsTrue(DraftSeriesCatalog.MenuUnlocked(series.GetMenu("rarity"), 10));
    }

    [Test]
    public void BrokenRowsAreDropped()
    {
        var file = new SeriesFile
        {
            menus = new List<SeriesMenu>
            {
                new SeriesMenu { id = "m", series = new List<SeriesDef>
                {
                    new SeriesDef { id = "ok", rounds = new List<SeriesRound> { new SeriesRound { track = "Daytona", baseLaps = 4 } }, restriction = null, prize = null },
                    new SeriesDef { id = "ok", rounds = new List<SeriesRound> { new SeriesRound { track = "Bristol", baseLaps = 10 } } },
                    new SeriesDef { id = "empty" },
                    new SeriesDef { id = "" , rounds = new List<SeriesRound> { new SeriesRound() } },
                    null,
                } },
                new SeriesMenu { id = "nothing" },
            },
        };
        var s = new DraftSeriesCatalog(file);
        Assert.AreEqual(1, s.All.Count);
        Assert.AreEqual(1, s.Menus.Count);
        Assert.AreEqual("Daytona", s.Get("ok").rounds[0].track);
        Assert.IsNotNull(s.Get("ok").restriction);
        Assert.IsTrue(s.Get("ok").prize.IsNone);
        Assert.AreEqual("m", s.Get("ok").menu);
        Assert.IsNull(DraftSeriesCatalog.FromJson(""));
        Assert.IsNull(DraftSeriesCatalog.FromJson("not json"));
    }

    // ---- Restrictions -----------------------------------------------------------------------------------

    [Test]
    public void EligibleWhenEverythingIsMet()
    {
        var r = new Restriction(5, 2, RestrictionRule.Team, "HEN");
        var e = Restrictions.Check(r, Car(team: "HEN"), 2, 5);
        Assert.IsTrue(e.Eligible, e.Summary);
        Assert.IsEmpty(e.Reasons);
        Assert.AreEqual("Eligible", e.Summary);
    }

    [Test]
    public void EveryFailingRequirementIsReportedInOrder()
    {
        var r = new Restriction(10, 3, RestrictionRule.Manufacturer, "FRD", minRarity: 3);
        var e = Restrictions.Check(r, Car(manu: "CHV", rarity: 2), 1, 4);
        Assert.IsFalse(e.Eligible);
        CollectionAssert.AreEqual(
            new[] { RestrictionFailure.PlayerLevel, RestrictionFailure.CarClass, RestrictionFailure.MinRarity, RestrictionFailure.Manufacturer },
            e.Reasons.Select(x => x.failure).ToArray());
        StringAssert.Contains("level 10", e.Summary);
        StringAssert.Contains("Class C", e.Summary);
        StringAssert.Contains("FRD", e.Summary);
    }

    [Test]
    public void UnownedCarsCantEnter()
    {
        var r = new Restriction(1, 0);
        var car = Car();
        var e = Restrictions.Check(r, car, Restrictions.NotOwned, 50);
        Assert.IsTrue(e.Has(RestrictionFailure.NotOwned));
        Assert.IsFalse(e.Has(RestrictionFailure.CarClass), "an unowned car has no class to be too low");

        var garage = new List<OwnedCar> { new OwnedCar("other_9", 6) };
        Assert.IsTrue(Restrictions.CheckInGarage(r, car, garage, 50).Has(RestrictionFailure.NotOwned));
        garage.Add(new OwnedCar(car.id, 0, 10));
        Assert.IsTrue(Restrictions.CheckInGarage(r, car, garage, 50).Eligible, "class 0 meets a class-0 series");
        Assert.IsTrue(Restrictions.Check(r, null, Restrictions.NotOwned, 50).Has(RestrictionFailure.NoCar));
    }

    [Test]
    public void ClassIsCheckedOnTheOwnedCar()
    {
        var r = new Restriction(1, 3);
        Assert.IsTrue(Restrictions.Check(r, Car(), new OwnedCar("t_1", 2), 1).Has(RestrictionFailure.CarClass));
        Assert.IsTrue(Restrictions.Check(r, Car(), new OwnedCar("t_1", 3), 1).Eligible);
        Assert.IsTrue(Restrictions.Check(r, Car(), new OwnedCar("t_1", 6), 1).Eligible);
        Assert.IsTrue(Restrictions.Check(r, Car(), (OwnedCar)null, 1).Has(RestrictionFailure.NotOwned));
    }

    [Test]
    public void EachRuleKindMatchesItsField()
    {
        var car = Car(id: "cup20_48", number: 48, team: "HEN", manu: "CHV", rarity: 3, type: "Legend", driver: "Johnson", carset: "cup20");
        void Fits(string rule, string value, bool expected) =>
            Assert.AreEqual(expected, Restrictions.CarFits(new Restriction(0, 0, rule, value), car), $"{rule}={value}");

        Fits(RestrictionRule.Team, "HEN", true);
        Fits(RestrictionRule.Team, "hen", true);
        Fits(RestrictionRule.Team, "JGR", false);
        Fits(RestrictionRule.Manufacturer, "CHV", true);
        Fits(RestrictionRule.Manufacturer, "FRD", false);
        Fits(RestrictionRule.Car, "48", true);          // DM2: the #48 of any carset
        Fits(RestrictionRule.Car, "24", false);
        Fits(RestrictionRule.Car, "cup20_48", true);    // or one car exactly
        Fits(RestrictionRule.Car, "cup24_48", false);
        Fits(RestrictionRule.Driver, "Johnson", true);
        Fits(RestrictionRule.Driver, "Gordon", false);
        Fits(RestrictionRule.Type, "Legend", true);
        Fits(RestrictionRule.Type, "Rookie", false);
        Fits(RestrictionRule.Rarity, "3", true);
        Fits(RestrictionRule.Rarity, "4", false);       // exact, as DM2's garage checked it
        Fits(RestrictionRule.Rarity, "2", false);
        Fits("", "", true);
        Fits(null, null, true);
    }

    [Test]
    public void MinRarityIsAFloorAndUnknownRulesFailClosed()
    {
        Assert.IsTrue(Restrictions.CarFits(new Restriction(0, 0, minRarity: 2), Car(rarity: 2)));
        Assert.IsTrue(Restrictions.CarFits(new Restriction(0, 0, minRarity: 2), Car(rarity: 4)));
        Assert.IsFalse(Restrictions.CarFits(new Restriction(0, 0, minRarity: 2), Car(rarity: 1)));

        var e = Restrictions.Check(new Restriction(0, 0, "Colour", "Red"), Car(), 6, 99);
        Assert.IsTrue(e.Has(RestrictionFailure.UnknownRule));
        Assert.IsFalse(RestrictionRule.IsValid("Colour"));
    }

    [Test]
    public void LevelGateAlone()
    {
        Assert.IsFalse(Restrictions.LevelUnlocked(new Restriction(10, 0), 9));
        Assert.IsTrue(Restrictions.LevelUnlocked(new Restriction(10, 0), 10));
        Assert.IsTrue(Restrictions.LevelUnlocked(null, 0));
    }

    [Test]
    public void DescribeListsEntryRequirementsLikeDm2()
    {
        CollectionAssert.AreEqual(new[] { "Level: 35+", "Driver Class: B+", "Team: PEN" },
            Restrictions.Describe(new Restriction(35, 4, RestrictionRule.Team, "PEN")));
        CollectionAssert.AreEqual(new[] { "Level: 1+", "Driver Class: R+" }, Restrictions.Describe(new Restriction(1, 0)));
        CollectionAssert.AreEqual(new[] { "Level: 0+", "Driver Class: R+", "Exact Car: #48" },
            Restrictions.Describe(new Restriction(0, 1, RestrictionRule.Car, "48")));
        CollectionAssert.AreEqual(new[] { "R", "R", "D", "C", "B", "A", "S" },
            Enumerable.Range(0, 7).Select(Restrictions.ClassLetter).ToArray());
    }

    [Test]
    public void RealSeriesAgainstARealGarage()
    {
        var series = LoadSeries();
        var cars = LoadCars();
        var lone = series.Get("team_lone_ranger");   // level 5, class 1, IND cars only
        var ind = cars.ByTeam("IND").First();
        var hen = cars.ByTeam("HEN").First();
        var garage = new List<OwnedCar> { new OwnedCar(ind.id, 1), new OwnedCar(hen.id, 6) };

        Assert.IsTrue(SeriesRules.CanEnter(lone, ind, garage, 5).Eligible);
        Assert.IsTrue(SeriesRules.CanEnter(lone, ind, garage, 4).Has(RestrictionFailure.PlayerLevel));
        Assert.IsTrue(SeriesRules.CanEnter(lone, hen, garage, 50).Has(RestrictionFailure.Team));
        CollectionAssert.AreEqual(new[] { ind.id },
            Restrictions.EligibleGarage(lone.restriction, cars, garage, 5).Select(o => o.id).ToArray());
    }

    // ---- Championships ----------------------------------------------------------------------------------

    static SeriesDef ThreeRounds(int aiLevel = 4) => new SeriesDef
    {
        id = "test_three",
        aiLevel = aiLevel,
        restriction = new Restriction(1, 0),
        rounds = new List<SeriesRound>
        {
            new SeriesRound { track = "Daytona", dm2Track = 1, baseLaps = 4 },
            new SeriesRound { track = "Bristol", dm2Track = 8, baseLaps = 10 },
            new SeriesRound { track = "Phoenix", dm2Track = 4, baseLaps = 6 },
        },
    };

    // Four cars in carset "a", one in "b".
    static CarCatalog SmallCatalog() => new CarCatalog(new CarCatalogFile
    {
        cars = new List<CarDef>
        {
            Car("a_1", 1, carset: "a"), Car("a_2", 2, carset: "a"), Car("a_3", 3, carset: "a"), Car("a_4", 4, carset: "a"),
            Car("b_9", 9, carset: "b"),
        },
    });

    [Test]
    public void CupPointsTable()
    {
        Assert.AreEqual(40, SeriesRules.PointsFor(1));
        Assert.AreEqual(35, SeriesRules.PointsFor(2));
        Assert.AreEqual(34, SeriesRules.PointsFor(3));
        Assert.AreEqual(1, SeriesRules.PointsFor(36));
        Assert.AreEqual(1, SeriesRules.PointsFor(40));
        Assert.AreEqual(0, SeriesRules.PointsFor(41));
        Assert.AreEqual(0, SeriesRules.PointsFor(0));
        for (int p = 2; p <= 40; p++) Assert.LessOrEqual(SeriesRules.PointsFor(p), SeriesRules.PointsFor(p - 1));
    }

    [Test]
    public void LapsAndDifficulty()
    {
        Assert.AreEqual(1, SeriesRules.DefaultLapsMultiplier(0));
        Assert.AreEqual(2, SeriesRules.DefaultLapsMultiplier(4));
        Assert.AreEqual(4, SeriesRules.DefaultLapsMultiplier(15));
        Assert.AreEqual(8, SeriesRules.RaceLaps(4, 4));          // Daytona at AI 4: 4 x 2
        Assert.AreEqual(12, SeriesRules.RaceLaps(4, 4, 3));      // a custom multiplier wins
        Assert.AreEqual(1, SeriesRules.RaceLaps(0, 0));
        Assert.AreEqual(50, SeriesRules.DifficultyPercent(0));
        Assert.AreEqual(150, SeriesRules.DifficultyPercent(10));
        var s = ThreeRounds(aiLevel: 6);
        Assert.AreEqual(6, SeriesRules.ClampDifficulty(s, 2), "never below the series' own");
        Assert.AreEqual(9, SeriesRules.ClampDifficulty(s, 9));
        Assert.AreEqual(SeriesRules.MaxAILevel, SeriesRules.ClampDifficulty(s, 99));
    }

    [Test]
    public void StartingLocksTheCarAndFieldsItsCarset()
    {
        var cars = SmallCatalog();
        var p = SeriesRules.Start(ThreeRounds(), cars.Get("a_2"), cars);
        Assert.AreEqual("test_three", p.seriesId);
        Assert.AreEqual("a_2", p.carId);
        Assert.AreEqual("a", p.carset);
        Assert.AreEqual(0, p.round);
        Assert.AreEqual(3, p.Length);
        Assert.IsFalse(p.IsComplete);
        CollectionAssert.AreEquivalent(new[] { "a_1", "a_2", "a_3", "a_4" }, p.table.Select(e => e.carId).ToArray());
        Assert.IsTrue(p.table.All(e => e.points == 0));
        Assert.AreEqual("Daytona", SeriesRules.NextRound(p).track);
        Assert.AreEqual(8, SeriesRules.NextRaceLaps(p));
        Assert.AreEqual(4, p.aiLevel);

        var harder = SeriesRules.Start(ThreeRounds(), cars.Get("a_2"), cars, aiLevel: 10, lapsMultiplier: 1);
        Assert.AreEqual(10, harder.aiLevel);
        Assert.AreEqual(4, SeriesRules.NextRaceLaps(harder));
        Assert.AreEqual(4, SeriesRules.Start(ThreeRounds(), cars.Get("a_2"), cars, aiLevel: 1).aiLevel, "can't go easier than the series");

        Assert.Throws<ArgumentException>(() => SeriesRules.Start(new SeriesDef { id = "none" }, cars.Get("a_2"), cars));
    }

    [Test]
    public void ARoundScoresTheFieldAndAdvances()
    {
        var cars = SmallCatalog();
        var p = SeriesRules.Start(ThreeRounds(), cars.Get("a_2"), cars);
        // An outsider in the order takes no position; a repeat counts once; a_4 isn't classified.
        var r = SeriesRules.RecordRace(p, new[] { "a_1", "b_9", "a_2", "a_1", "a_3" });
        Assert.AreEqual(1, r.round);
        Assert.AreEqual(2, r.playerFinish);
        Assert.AreEqual(35, r.playerPoints);
        Assert.IsFalse(r.championshipOver);
        Assert.AreEqual(1, p.round);
        Assert.AreEqual("Bristol", SeriesRules.NextRound(p).track);

        var table = SeriesRules.Standings(p);
        CollectionAssert.AreEqual(new[] { "a_1", "a_2", "a_3", "a_4" }, table.Select(e => e.carId).ToArray());
        CollectionAssert.AreEqual(new[] { 40, 35, 34, 0 }, table.Select(e => e.points).ToArray());
        Assert.AreEqual(1, table[0].wins);
        Assert.AreEqual(0, table[3].races);
        Assert.AreEqual(2, SeriesRules.Position(p));
        Assert.AreEqual(0, SeriesRules.Position(p, "b_9"));
        CollectionAssert.AreEqual(new[] { 2 }, p.playerFinishes);
    }

    [Test]
    public void TiesGoToWinsThenBestFinish()
    {
        var cars = SmallCatalog();
        var series = ThreeRounds();
        series.rounds.Add(new SeriesRound { track = "Dover", baseLaps = 8 });
        var p = SeriesRules.Start(series, cars.Get("a_1"), cars);
        SeriesRules.RecordRace(p, new[] { "a_1", "a_2", "a_3", "a_4" });   // a_1 40, a_2 35
        SeriesRules.RecordRace(p, new[] { "a_2", "a_1", "a_3", "a_4" });   // a_1 75, a_2 75: one win each, both best 1st
        var t = SeriesRules.Standings(p);
        Assert.AreEqual(75, t[0].points);
        Assert.AreEqual(75, t[1].points);
        Assert.AreEqual("a_1", t[0].carId, "level on points, wins and best finish: lower number first");

        SeriesRules.RecordRace(p, new[] { "a_3", "a_4", "a_1", "a_2" });   // a_1 109, a_2 108
        SeriesRules.RecordRace(p, new[] { "a_2", "a_3", "a_4", "a_1" });   // a_1 142, a_2 148 -> a_2 leads on points
        t = SeriesRules.Standings(p);
        Assert.AreEqual("a_2", t[0].carId);
        Assert.AreEqual(2, t[0].wins);
    }

    [Test]
    public void TheLastRoundEndsItAndRewardsAreCollectedOnce()
    {
        var cars = SmallCatalog();
        var p = SeriesRules.Start(ThreeRounds(), cars.Get("a_3"), cars);
        Assert.IsFalse(SeriesRules.CanCollectRewards(p));
        Assert.IsFalse(SeriesRules.CollectRewards(p));
        SeriesRules.RecordRace(p, new[] { "a_3", "a_1", "a_2", "a_4" });
        SeriesRules.RecordRace(p, new[] { "a_3", "a_1", "a_2", "a_4" });
        var last = SeriesRules.RecordRace(p, new[] { "a_1", "a_3", "a_2", "a_4" });
        Assert.IsTrue(last.championshipOver);
        Assert.IsTrue(p.IsComplete);
        Assert.IsNull(SeriesRules.NextRound(p));
        Assert.AreEqual(0, SeriesRules.NextRaceLaps(p));
        Assert.Throws<InvalidOperationException>(() => SeriesRules.RecordRace(p, new[] { "a_3" }));
        Assert.AreEqual(1, SeriesRules.Position(p));

        Assert.IsTrue(SeriesRules.CanCollectRewards(p));
        Assert.IsTrue(SeriesRules.CollectRewards(p));
        Assert.IsFalse(SeriesRules.CollectRewards(p), "DM2's infinite-rewards guard: only once");
    }

    [Test]
    public void FinishedChampionshipsFoldIntoTheSeriesRecord()
    {
        var cars = SmallCatalog();
        var records = new List<SeriesRecord>();
        var p = SeriesRules.Start(ThreeRounds(), cars.Get("a_4"), cars);
        Assert.Throws<InvalidOperationException>(() => SeriesRules.RecordChampionship(records, p));
        for (int i = 0; i < 3; i++) SeriesRules.RecordRace(p, new[] { "a_1", "a_4" });
        var rec = SeriesRules.RecordChampionship(records, p);
        Assert.AreEqual(1, records.Count);
        Assert.AreEqual(1, rec.championships);
        Assert.AreEqual(0, rec.titles);
        Assert.AreEqual(2, rec.bestFinish);

        var q = SeriesRules.Start(ThreeRounds(), cars.Get("a_4"), cars);
        for (int i = 0; i < 3; i++) SeriesRules.RecordRace(q, new[] { "a_4", "a_1" });
        rec = SeriesRules.RecordChampionship(records, q);
        Assert.AreEqual(1, records.Count);
        Assert.AreEqual(2, rec.championships);
        Assert.AreEqual(1, rec.titles);
        Assert.AreEqual(1, rec.bestFinish);
    }

    [Test]
    public void ProgressSurvivesASaveAndASanitise()
    {
        var cars = SmallCatalog();
        var p = SeriesRules.Start(ThreeRounds(), cars.Get("a_2"), cars);
        SeriesRules.RecordRace(p, new[] { "a_2", "a_1" });
        var json = ProfileJson.Write(p, false);
        var back = (ChampionshipProgress)ProfileJson.Read(json, typeof(ChampionshipProgress));
        Assert.AreEqual(p.seriesId, back.seriesId);
        Assert.AreEqual(1, back.round);
        Assert.AreEqual(3, back.Length);
        Assert.AreEqual(40, back.table.Single(e => e.carId == "a_2").points);
        Assert.AreEqual(1, SeriesRules.Position(back));
        Assert.AreEqual("Bristol", SeriesRules.NextRound(back).track);

        back.round = 99;
        back.aiLevel = -3;
        back.table.Add(null);
        back.playerFinishes = null;
        SeriesRules.Sanitise(back);
        Assert.AreEqual(3, back.round);
        Assert.IsTrue(back.IsComplete);
        Assert.AreEqual(0, back.aiLevel);
        Assert.AreEqual(4, back.table.Count);
        Assert.IsNotNull(back.playerFinishes);
    }

    [Test]
    public void RealSeriesRunsAsAChampionship()
    {
        var series = LoadSeries();
        var cars = LoadCars();
        var s = series.Get("cookie_cutters_one_point_five");
        var car = cars.InCarset("cup24").First();
        var p = SeriesRules.Start(s, car, cars);
        Assert.AreEqual(cars.InCarset("cup24").Count, p.table.Count);
        var order = cars.InCarset("cup24").Select(c => c.id).ToList();
        while (!p.IsComplete) SeriesRules.RecordRace(p, order);
        Assert.AreEqual(1, SeriesRules.Position(p));
        Assert.AreEqual(40 * s.RoundCount, SeriesRules.Standings(p)[0].points);
    }
